/**
 * Express Application — Main app configuration
 * Mounts all middleware, routes, and error handlers.
 * Generated by BackendForge
 */

const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const morgan = require('morgan');
const compression = require('compression');
const { env } = require('./config/env');

// ─── Middleware ──────────────────────────────────────────────
const { rateLimiter } = require('./middleware/rate-limiter.middleware');
const { errorHandler, notFoundHandler } = require('./middleware/error-handler.middleware');
const { requestIdMiddleware } = require('./middleware/auth.middleware');

// ─── Routes ─────────────────────────────────────────────────
const authRoutes = require('./routes/auth.routes');
const userRoutes = require('./routes/user.routes');
const productRoutes = require('./routes/product.routes');
const cartRoutes = require('./routes/cart.routes');
const orderRoutes = require('./routes/order.routes');
const paymentRoutes = require('./routes/payment.routes');
const adminRoutes = require('./routes/admin.routes');
const reviewRoutes = require('./routes/review.routes');

const app = express();

// ─── Security Headers ───────────────────────────────────────
app.use(helmet({
  contentSecurityPolicy: false, // Disabled for API-only servers
  crossOriginResourcePolicy: { policy: 'cross-origin' },
}));

// ─── CORS ───────────────────────────────────────────────────
const corsOrigins = env.CORS_ORIGINS
  ? env.CORS_ORIGINS.split(',').map(s => s.trim())
  : ['http://localhost:3000', 'http://localhost:5173', 'http://localhost:3001'];

app.use(cors({
  origin: corsOrigins,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Request-ID'],
  exposedHeaders: ['X-Request-ID', 'X-Total-Count'],
}));

// ─── Body Parsing ───────────────────────────────────────────
// Raw body needed for webhook signature verification
app.use('/api/webhooks', express.raw({ type: 'application/json' }));
// JSON body for everything else
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

// ─── Compression ────────────────────────────────────────────
app.use(compression());

// ─── Request Logging ────────────────────────────────────────
if (env.NODE_ENV !== 'test') {
  app.use(morgan(env.NODE_ENV === 'production' ? 'combined' : 'dev'));
}

// ─── Request ID ─────────────────────────────────────────────
app.use(requestIdMiddleware);

// ─── Rate Limiting ──────────────────────────────────────────
app.use('/api/', rateLimiter);

// ─── Health Check ───────────────────────────────────────────
app.get('/api/health', (req, res) => {
  res.json({
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: env.NODE_ENV,
    version: require('../package.json').version,
  });
});

// ─── API Routes ─────────────────────────────────────────────
app.use('/api/auth', authRoutes);
app.use('/api/users', userRoutes);
app.use('/api/products', productRoutes);
app.use('/api/cart', cartRoutes);
app.use('/api/orders', orderRoutes);
app.use('/api/payments', paymentRoutes);
app.use('/api/webhooks', require('./webhooks/payment-webhook'));
app.use('/api/admin', adminRoutes);
app.use('/api/reviews', reviewRoutes);

// ─── API Documentation ─────────────────────────────────────
app.get('/api/docs', (req, res) => {
  res.json({
    name: 'demo-store-backend API',
    version: '1.0.0',
    endpoints: {
      auth: {
        'POST /api/auth/register': 'Register a new customer',
        'POST /api/auth/login': 'Login with email/password',
        'POST /api/auth/admin/login': 'Admin login (step 1)',
        'POST /api/auth/admin/verify-otp': 'Admin OTP verification (step 2)',
        'POST /api/auth/refresh': 'Refresh access token',
        'POST /api/auth/forgot-password': 'Request password reset',
        'POST /api/auth/logout': 'Logout and invalidate token',
      },
      users: {
        'GET /api/users/profile': 'Get own profile',
        'PUT /api/users/profile': 'Update profile (including phone)',
        'PUT /api/users/addresses': 'Manage addresses',
        'GET /api/users/orders': 'Get own order history',
      },
      products: {
        'GET /api/products': 'List products (search, filter, paginate)',
        'GET /api/products/:id': 'Get product detail',
        'POST /api/products': 'Create product (admin)',
        'PUT /api/products/:id': 'Update product (admin)',
        'DELETE /api/products/:id': 'Delete product (admin)',
      },
      cart: {
        'GET /api/cart': 'Get cart',
        'POST /api/cart': 'Add item to cart',
        'PUT /api/cart/:itemId': 'Update cart item quantity',
        'DELETE /api/cart/:itemId': 'Remove item from cart',
        'DELETE /api/cart': 'Clear cart',
      },
      orders: {
        'POST /api/orders': 'Place a new order',
        'GET /api/orders/:id': 'Get order details',
        'POST /api/orders/:id/cancel': 'Cancel order (within 2 hours)',
      },
      payments: {
        'POST /api/payments/create-intent': 'Create payment intent',
        'GET /api/payments/:orderId': 'Get payment status',
        'POST /api/webhooks/stripe': 'Payment webhook (auto-called by gateway)',
      },
      admin: {
        'GET /api/admin/dashboard': 'Dashboard stats',
        'GET /api/admin/orders': 'All orders with customer details',
        'PUT /api/admin/orders/:id/status': 'Update shipping status',
        'GET /api/admin/customers': 'Customer list',
        'GET /api/admin/account': 'Admin own profile',
        'GET /api/admin/audit-log': 'Admin activity log',
        'GET /api/admin/cancellations': 'Cancelled orders',
      },
      reviews: {
        'GET /api/reviews/:productId': 'Get product reviews',
        'POST /api/reviews': 'Submit a review',
        'PUT /api/reviews/:id': 'Update own review',
        'DELETE /api/reviews/:id': 'Delete review (admin/owner)',
      },
      system: {
        'GET /api/health': 'Health check',
        'GET /api/docs': 'This documentation',
      },
    },
  });
});

// ─── 404 Handler ────────────────────────────────────────────
app.use(notFoundHandler);

// ─── Error Handler (must be last) ───────────────────────────
app.use(errorHandler);

module.exports = app;
